function longestVowelRun(word: string): number {
  let best = 0;
  for (let i = 0; i < word.length; i++) {
    if (word[i] !== "a") continue;
    const seen = new Set<string>([word[i]]);
    for (let j = i + 1; j < word.length && word[j] >= word[j - 1]; j++) {
      seen.add(word[j]);
      if (seen.size === 5) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

