function longestVowelRun(word: string): number {
  let best = 0, len = 1, kinds = 1;
  for (let i = 1; i < word.length; i++) {
    if (word[i] < word[i - 1]) {
      len = 1;
      kinds = 1;
    } else {
      len++;
      if (word[i] !== word[i - 1]) kinds++;
    }
    if (kinds === 5) best = Math.max(best, len);
  }
  return best;
}

